solution.code:
const PERINGKAT = { member: 0, admin: 1, owner: 2 };
const canManage = (actor, target) => actor !== "member" && PERINGKAT[actor] > PERINGKAT[target];
const MILIK_TENANT = ["memberships", "invites", "bookings", "audit_log", "billing_orders"];
const GAGAL = ["deny", "cancel", "expire", "failure"];

function buatInti({ jam, serverKey, acak }) {
  const db = buatDb();
  db.tabel.plans = JSON.parse(JSON.stringify(PLANS));
  const orgAktif = (tx) => tx.currentSetting("app.org_id");

  // RLS: app_user only sees its tenant; app_system (webhook, worker) gets an explicit using(true).
  for (const t of [...MILIK_TENANT, "orgs"]) {
    db.aktifkanRls(t);
    db.policy(t, { peran: "app_system", using: () => true });
  }
  for (const t of MILIK_TENANT) {
    db.policy(t, { peran: "app_user", using: (b, tx) => b.org_id === orgAktif(tx) ||
      (t === "memberships" && b.user_id === tx.currentSetting("app.user_id")),
      withCheck: (b, tx) => b.org_id === orgAktif(tx) });
  }
  db.policy("orgs", { peran: "app_user", using: (b, tx) => b.id === orgAktif(tx) });

  async function sebagai(peran, fn) {
    const lama = db.peran;
    db.peran = peran;
    try { return await db.transaksi(fn); } finally { db.peran = lama; }
  }

  async function withTenant(userId, orgId, fn) {
    return sebagai("app_user", async (tx) => {
      tx.setConfig("app.user_id", userId);
      const m = tx.select("memberships", { org_id: orgId, user_id: userId });
      if (m.length === 0) throw new Forbidden("Kamu bukan anggota organisasi ini.");
      tx.setConfig("app.org_id", orgId);
      return fn(tx, m[0].role);
    });
  }

  function buatRepo(tx) {
    const org = orgAktif(tx);
    if (!org) throw new Error("tenant_wajib");
    const bersih = ({ org_id, ...isi }) => isi;
    return {
      daftar: (t, f = {}) => tx.select(t, { ...f, org_id: org }),
      buat: (t, data) => tx.insert(t, { ...bersih(data), org_id: org }),
      ubah: (t, f, ubah) => tx.update(t, { ...f, org_id: org }, bersih(ubah)),
      hapus: (t, f) => tx.delete(t, { ...f, org_id: org }),
    };
  }

  const audit = (tx, entri) => tx.insert("audit_log", { meta: {}, target: null, ...entri, created_at: jam.t });
  const bulan = (t) => new Date(t).toISOString().slice(0, 7);

  return {
    db, buatRepo,

    // Like a narrow SECURITY DEFINER function: runs as the owner, creates the org and its owner.
    async buatOrg(userId, nama) {
      return sebagai("pemilik", (tx) => {
        const id = "org-" + (tx.select("orgs").length + 1);
        tx.insert("orgs", { id, name: nama, plan_id: "gratis", paid_until: null, created_at: jam.t });
        tx.insert("memberships", { org_id: id, user_id: userId, role: "owner" });
        audit(tx, { org_id: id, actor_id: userId, action: "org.created", target: id });
        return id;
      });
    },

    async repo(userId, orgId) {
      await withTenant(userId, orgId, () => null); // Forbidden for non-members
      const jalan = (fn) => withTenant(userId, orgId, (tx) => fn(buatRepo(tx), tx));
      return {
        bookings: {
          daftar: () => jalan((r) => r.daftar("bookings")),
          // Kuota dihitung di transaksi yang sama. Di Postgres sungguhan, kunci baris orgs dengan `for update` agar dua booking serentak tidak lolos bersamaan.
          buat: (data) => jalan((r, tx) => {
            const [org] = tx.select("orgs", { id: orgId });
            const [plan] = tx.select("plans", { id: org.plan_id });
            const kini = bulan(jam.t);
            const terpakai = r.daftar("bookings").filter((b) => bulan(b.created_at) === kini).length;
            if (terpakai >= plan.max_bookings_per_month) {
              const err = new Error("plan_limit:bookings");
              err.status = 402;
              throw err;
            }
            return r.buat("bookings", { client_name: data.client_name, starts_at: data.starts_at, created_at: jam.t });
          }),
          hapus: (id) => jalan((r) => r.hapus("bookings", { id })),
        },
      };
    },

    async undang(userId, orgId, email, role) {
      return withTenant(userId, orgId, (tx, peranku) => {
        if (!canManage(peranku, role)) throw new Forbidden("Role kamu tidak boleh mengundang " + role + ".");
        const token = acak();
        const alamat = email.trim().toLowerCase();
        buatRepo(tx).buat("invites", { email: alamat, role, token_hash: sha256Hex(token),
          expires_at: jam.t + 7 * HARI, accepted_at: null });
        audit(tx, { org_id: orgId, actor_id: userId, action: "invite.created", target: alamat });
        return token;
      });
    },

    // The invitee is not a member yet, so this runs as a narrow system function.
    async terimaUndangan(userId, emailSesi, token) {
      return sebagai("app_system", (tx) => {
        const email = emailSesi.trim().toLowerCase();
        const [inv] = tx.select("invites", (i) => i.token_hash === sha256Hex(token) &&
          i.accepted_at === null && i.expires_at > jam.t && i.email === email);
        if (!inv) throw new Error("undangan_tidak_valid");
        tx.update("invites", { id: inv.id }, { accepted_at: jam.t });
        tx.insert("memberships", { org_id: inv.org_id, user_id: userId, role: inv.role });
        audit(tx, { org_id: inv.org_id, actor_id: userId, action: "invite.accepted", target: email });
        return inv.org_id;
      });
    },

    async buatTagihan(userId, orgId) {
      return withTenant(userId, orgId, (tx, peranku) => {
        if (peranku !== "owner") throw new Forbidden("Hanya owner yang boleh mengelola langganan.");
        const order_id = "sub-" + orgId + "-" + bulan(jam.t).replace("-", "");
        buatRepo(tx).buat("billing_orders", { order_id, plan_id: "pro", gross_amount: 299000, status: "pending" });
        return order_id;
      });
    },

    async webhook(n) {
      const { order_id, status_code, gross_amount, signature_key, transaction_status: st } = n || {};
      if (!order_id || !status_code || !gross_amount || !signature_key ||
          !timingSafeEqualTeks(signature_key, sha512Hex(order_id + status_code + gross_amount + serverKey))) {
        return { status: 401 };
      }
      try {
        const hasil = await sebagai("app_system", (tx) => {
          const key = order_id + ":" + st;
          if (tx.select("webhook_events", { provider: "midtrans", event_key: key }).length) return "duplikat";
          tx.insert("webhook_events", { provider: "midtrans", event_key: key });
          const [o] = tx.select("billing_orders", { order_id });
          if (GAGAL.includes(st)) {
            if (o && o.status === "pending") tx.update("billing_orders", { order_id }, { status: "failed" });
            return "gagal";
          }
          const sukses = st === "settlement" || (st === "capture" && n.fraud_status === "accept");
          if (!sukses || !o || o.status === "paid" || o.gross_amount !== Number(gross_amount)) return "diabaikan";
          tx.update("billing_orders", { order_id }, { status: "paid", paid_at: jam.t });
          const [org] = tx.select("orgs", { id: o.org_id });
          tx.update("orgs", { id: o.org_id }, { plan_id: o.plan_id,
            paid_until: Math.max(org.paid_until ?? 0, jam.t) + BULAN });
          audit(tx, { org_id: o.org_id, actor_id: "system:midtrans", action: "billing.paid", target: order_id });
          return "dibayar";
        });
        return { status: 200, hasil };
      } catch (e) {
        return { status: 500 };
      }
    },
  };
}

