// Pure-JS SHA-256 / SHA-512 (hex) for node:vm exercises (no crypto in the sandbox). Paste into `setup`.
// sha256Hex(teks) and sha512Hex(teks) match node:crypto createHash(...).update(teks).digest("hex").
function _utf8(s) { const b = unescape(encodeURIComponent(s)); return Array.from(b, (c) => c.charCodeAt(0)); }
function sha256Hex(teks) {
  const K = [], H = [];
  const frac = (x) => ((x - Math.floor(x)) * 4294967296) >>> 0;
  for (let n = 2, c = 0; c < 64; n++) { let p = true; for (let d = 2; d * d <= n; d++) if (n % d === 0) { p = false; break; } if (p) { if (c < 8) H.push(frac(Math.sqrt(n))); K.push(frac(Math.cbrt(n))); c++; } }
  const m = _utf8(teks), l = m.length * 8; m.push(0x80); while (m.length % 64 !== 56) m.push(0);
  for (let i = 7; i >= 0; i--) m.push(i > 3 ? 0 : (l >>> (i * 8)) & 255);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < m.length; o += 64) {
    const w = []; for (let i = 0; i < 64; i++) w[i] = i < 16 ? ((m[o + 4 * i] << 24) | (m[o + 4 * i + 1] << 16) | (m[o + 4 * i + 2] << 8) | m[o + 4 * i + 3]) >>> 0
      : (((r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10)) + w[i - 7] + (r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3)) + w[i - 16]) >>> 0);
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H.forEach((v, i) => (H[i] = (v + [a, b, c, d, e, f, g, h][i]) >>> 0));
  }
  return H.map((v) => v.toString(16).padStart(8, "0")).join("");
}
function sha512Hex(teks) {
  const M = (1n << 64n) - 1n, K = [], H = [];
  const isqrt = (n) => { let x = n, y = (x + 1n) / 2n; while (y < x) { x = y; y = (x + n / x) / 2n; } return x; };
  const icbrt = (n) => { let x = 1n << BigInt(Math.ceil(n.toString(2).length / 3) + 1); for (;;) { const y = (2n * x + n / (x * x)) / 3n; if (y >= x) return x; x = y; } };
  for (let n = 2, c = 0; c < 80; n++) { let p = true; for (let d = 2; d * d <= n; d++) if (n % d === 0) { p = false; break; } if (p) { const N = BigInt(n); if (c < 8) H.push(isqrt(N << 128n) & M); K.push(icbrt(N << 192n) & M); c++; } }
  const m = _utf8(teks), l = m.length * 8; m.push(0x80); while (m.length % 128 !== 112) m.push(0);
  for (let i = 15; i >= 0; i--) m.push(i > 3 ? 0 : (l >>> (i * 8)) & 255);
  const r = (x, n) => ((x >> n) | (x << (64n - n))) & M;
  for (let o = 0; o < m.length; o += 128) {
    const w = [];
    for (let i = 0; i < 80; i++) {
      if (i < 16) { let v = 0n; for (let j = 0; j < 8; j++) v = (v << 8n) | BigInt(m[o + 8 * i + j]); w[i] = v; continue; }
      const s0 = r(w[i - 15], 1n) ^ r(w[i - 15], 8n) ^ (w[i - 15] >> 7n), s1 = r(w[i - 2], 19n) ^ r(w[i - 2], 61n) ^ (w[i - 2] >> 6n);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) & M;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 80; i++) {
      const t1 = (h + (r(e, 14n) ^ r(e, 18n) ^ r(e, 41n)) + ((e & f) ^ (~e & M & g)) + K[i] + w[i]) & M;
      const t2 = ((r(a, 28n) ^ r(a, 34n) ^ r(a, 39n)) + ((a & b) ^ (a & c) ^ (b & c))) & M;
      h = g; g = f; f = e; e = (d + t1) & M; d = c; c = b; b = a; a = (t1 + t2) & M;
    }
    H.forEach((v, i) => (H[i] = (v + [a, b, c, d, e, f, g, h][i]) & M));
  }
  return H.map((v) => v.toString(16).padStart(16, "0")).join("");
}
// mini-pg: tiny in-memory Postgres look-alike with Row Level Security (exercise shim, no real SQL).
// db.tabel.<name> = array of rows. db.peran = "app_user" | "app_system" | "pemilik" (table owner).
// The owner bypasses RLS unless db.paksaRls(t) (= FORCE ROW LEVEL SECURITY).
// RLS on + no policy for the current role = default-deny (zero rows). using() not true hides rows
// silently; withCheck() (defaults to using) not true on insert/update throws, like Postgres.
// tx.setConfig is transaction-local like set_config(..., true); an error inside transaksi rolls back.
function buatDb() {
  const tabel = {}, rls = {};
  let seq = 0;
  const salin = (x) => JSON.parse(JSON.stringify(x));
  const cocok = (b, f) => !f || (typeof f === "function" ? f(b) : Object.keys(f).every((k) => b[k] === f[k]));
  const aturan = (t) => (rls[t] ??= { aktif: false, paksa: false, policy: [] });
  const db = {
    tabel, peran: "app_user",
    aktifkanRls(t) { aturan(t).aktif = true; },
    paksaRls(t) { aturan(t).aktif = true; rls[t].paksa = true; },
    matikanRls(t) { aturan(t).aktif = false; },
    policy(t, p) { aturan(t).policy.push(p); },
    async transaksi(fn) {
      const cfg = {}, cadangan = JSON.stringify(tabel);
      const kena = (t) => !!(rls[t] && rls[t].aktif) && (db.peran !== "pemilik" || rls[t].paksa);
      const milik = (t) => aturan(t).policy.filter((p) => !p.peran || p.peran === db.peran);
      const lihat = (t, b) => !kena(t) || milik(t).some((p) => p.using(b, tx) === true);
      const cek = (t, b) => {
        if (kena(t) && !milik(t).some((p) => (p.withCheck || p.using)(b, tx) === true))
          throw new Error(`new row violates row-level security policy for table "${t}"`);
      };
      const tx = {
        setConfig(n, v) { cfg[n] = v == null ? "" : String(v); },
        currentSetting(n) { return cfg[n] ? cfg[n] : null; },
        select(t, f) { return (tabel[t] || []).filter((b) => lihat(t, b) && cocok(b, f)).map(salin); },
        insert(t, baris) { const b = { id: ++seq, ...salin(baris) }; cek(t, b); (tabel[t] ??= []).push(b); return salin(b); },
        update(t, f, ubah) {
          const kenaUbah = (tabel[t] || []).filter((b) => lihat(t, b) && cocok(b, f));
          const baru = kenaUbah.map((b) => ({ ...b, ...salin(ubah) }));
          baru.forEach((b) => cek(t, b));
          kenaUbah.forEach((b, i) => Object.assign(b, baru[i]));
          return kenaUbah.length;
        },
        delete(t, f) {
          const semua = tabel[t] || [], hapus = semua.filter((b) => lihat(t, b) && cocok(b, f));
          tabel[t] = semua.filter((b) => !hapus.includes(b));
          return hapus.length;
        },
      };
      try { return await fn(tx); } catch (e) {
        for (const k of Object.keys(tabel)) delete tabel[k];
        Object.assign(tabel, JSON.parse(cadangan));
        throw e;
      }
    },
  };
  return db;
}
class Forbidden extends Error { constructor(pesan) { super(pesan); this.status = 403; } }
// Project helpers: fake Midtrans, a whole-string compare (stand-in for timingSafeEqual), and siapkan().
function buatMidtransPalsu(serverKey) {
  return {
    // Builds an HTTP notification body with a correct signature_key, like Midtrans does.
    buatNotifikasi({ order_id, status_code = "200", gross_amount = "299000.00", transaction_status, fraud_status }) {
      return { order_id, status_code, gross_amount, transaction_status, fraud_status, payment_type: "qris",
        signature_key: sha512Hex(order_id + status_code + gross_amount + serverKey) };
    },
  };
}
function timingSafeEqualTeks(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let beda = 0;
  for (let i = 0; i < a.length; i++) beda |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return beda === 0;
}
const HARI = 24 * 60 * 60 * 1000, BULAN = 30 * HARI; // "1 month" simplified to 30 days
const SERVER_KEY = "SB-Mid-server-uji";
const PLANS = [
  { id: "gratis", max_staff: 2, max_bookings_per_month: 100, price_idr: 0 },
  { id: "pro", max_staff: 20, max_bookings_per_month: 5000, price_idr: 299000 },
];
// Fresh core per test: fake clock at 1 Dec 2026 (UTC) and a deterministic acak().
function siapkan() {
  const jam = { t: Date.UTC(2026, 11, 1), maju(ms) { this.t += ms; } };
  let n = 0;
  const acak = () => "tok" + ++n + "-Zq8vK1mPx3"; // stand-in for randomBytes(32).toString("base64url")
  return { jam, inti: buatInti({ jam, serverKey: SERVER_KEY, acak }), midtrans: buatMidtransPalsu(SERVER_KEY) };
}
// Two clinics with one booking each (uses your buatOrg, repo, and bookings.buat).
async function duaKlinik() {
  const s = siapkan();
  s.A = await s.inti.buatOrg("u-sari", "Klinik Gigi Senyum");
  s.B = await s.inti.buatOrg("u-raka", "Klinik Hewan Sahabat");
  s.rA = await s.inti.repo("u-sari", s.A);
  s.rB = await s.inti.repo("u-raka", s.B);
  await s.rA.bookings.buat({ client_name: "Budi", starts_at: "2026-12-03T09:00:00Z" });
  await s.rB.bookings.buat({ client_name: "Kucing Oyen", starts_at: "2026-12-03T10:00:00Z" });
  return s;
}
const gagalDengan = (p) => p.then(() => null, (e) => e);

