function tenantDariRequest({ host, path }, domainUtama) {
  const h = host.toLowerCase().split(":")[0];
  const akhiran = "." + domainUtama.toLowerCase();
  if (h.endsWith(akhiran)) {
    const sub = h.slice(0, -akhiran.length);
    if (sub && !sub.includes(".") && sub !== "www") return { dari: "subdomain", org: sub };
  }
  const seg = path.split("?")[0].split("/").filter(Boolean);
  if (seg[0] === "orgs" && seg[1]) return { dari: "path", org: seg[1] };
  return null;
}

