// mini-pg: tiny in-memory Postgres look-alike with Row Level Security (exercise shim, no real SQL).
// db.tabel.<name> = array of rows. db.peran = "app_user" | "app_system" | "pemilik" (table owner).
// The owner bypasses RLS unless db.paksaRls(t) (= FORCE ROW LEVEL SECURITY).
// RLS on + no policy for the current role = default-deny (zero rows). using() not true hides rows
// silently; withCheck() (defaults to using) not true on insert/update throws, like Postgres.
// tx.setConfig is transaction-local like set_config(..., true); an error inside transaksi rolls back.
function buatDb() {
  const tabel = {}, rls = {};
  let seq = 0;
  const salin = (x) => JSON.parse(JSON.stringify(x));
  const cocok = (b, f) => !f || (typeof f === "function" ? f(b) : Object.keys(f).every((k) => b[k] === f[k]));
  const aturan = (t) => (rls[t] ??= { aktif: false, paksa: false, policy: [] });
  const db = {
    tabel, peran: "app_user",
    aktifkanRls(t) { aturan(t).aktif = true; },
    paksaRls(t) { aturan(t).aktif = true; rls[t].paksa = true; },
    matikanRls(t) { aturan(t).aktif = false; },
    policy(t, p) { aturan(t).policy.push(p); },
    async transaksi(fn) {
      const cfg = {}, cadangan = JSON.stringify(tabel);
      const kena = (t) => !!(rls[t] && rls[t].aktif) && (db.peran !== "pemilik" || rls[t].paksa);
      const milik = (t) => aturan(t).policy.filter((p) => !p.peran || p.peran === db.peran);
      const lihat = (t, b) => !kena(t) || milik(t).some((p) => p.using(b, tx) === true);
      const cek = (t, b) => {
        if (kena(t) && !milik(t).some((p) => (p.withCheck || p.using)(b, tx) === true))
          throw new Error(`new row violates row-level security policy for table "${t}"`);
      };
      const tx = {
        setConfig(n, v) { cfg[n] = v == null ? "" : String(v); },
        currentSetting(n) { return cfg[n] ? cfg[n] : null; },
        select(t, f) { return (tabel[t] || []).filter((b) => lihat(t, b) && cocok(b, f)).map(salin); },
        insert(t, baris) { const b = { id: ++seq, ...salin(baris) }; cek(t, b); (tabel[t] ??= []).push(b); return salin(b); },
        update(t, f, ubah) {
          const kenaUbah = (tabel[t] || []).filter((b) => lihat(t, b) && cocok(b, f));
          const baru = kenaUbah.map((b) => ({ ...b, ...salin(ubah) }));
          baru.forEach((b) => cek(t, b));
          kenaUbah.forEach((b, i) => Object.assign(b, baru[i]));
          return kenaUbah.length;
        },
        delete(t, f) {
          const semua = tabel[t] || [], hapus = semua.filter((b) => lihat(t, b) && cocok(b, f));
          tabel[t] = semua.filter((b) => !hapus.includes(b));
          return hapus.length;
        },
      };
      try { return await fn(tx); } catch (e) {
        for (const k of Object.keys(tabel)) delete tabel[k];
        Object.assign(tabel, JSON.parse(cadangan));
        throw e;
      }
    },
  };
  return db;
}
class Forbidden extends Error { constructor(pesan) { super(pesan); this.status = 403; } }

// Sample data: two clinics. memberships has its own RLS: a user only sees their own rows.
function siapkan() {
  const db = buatDb();
  db.tabel.memberships = [
    { org_id: "A", user_id: "rani", role: "owner" },
    { org_id: "B", user_id: "budi", role: "owner" },
  ];
  db.tabel.bookings = [
    { id: "a1", org_id: "A", client_name: "Sari" },
    { id: "a2", org_id: "A", client_name: "Tono" },
    { id: "b1", org_id: "B", client_name: "Kucing Oyen" },
  ];
  db.aktifkanRls("memberships");
  db.policy("memberships", { using: (b, tx) => b.user_id === tx.currentSetting("app.user_id") });
  pasangRls(db);
  return db;
}
const tolak = (p) => p.then(() => null, (e) => e);

chapters.body:
## Tujuan

- Menambah lapisan kedua di atas RLS: repository yang mewajibkan tenant dan mengisi `org_id` sendiri.
- Menyusun daftar tes serangan lintas tenant yang wajib lulus.
- Menjalankan tes isolasi terhadap Postgres sungguhan dan membuktikan tes itu bisa merah.
- Menjaga agar route web tidak pernah memakai koneksi sistem.

## Pertahanan berlapis

RLS sudah membuat database menolak baris tenant lain. Kenapa masih perlu lapisan lagi? Karena setiap lapisan bisa gagal dengan caranya sendiri. Migrasi baru bisa lupa mengaktifkan RLS di tabel yang baru dibuat. Seseorang bisa tidak sengaja memakai koneksi pemilik saat debugging. Policy bisa salah ketik. Pertahanan berlapis artinya satu kesalahan tidak langsung berubah menjadi kebocoran.

Lapisan kedua ada di kode aplikasi, berupa **repository dengan tenant wajib**. Repository adalah kumpulan fungsi akses data, misalnya `daftar`, `buat`, `ubah`, dan `hapus`, yang dipakai semua route. Aturannya:

1. **Tanpa konteks tenant, langsung gagal.** Kalau `app.org_id` belum terpasang, repository melempar error `tenant_wajib` dan tidak menjalankan query apa pun. Gagal dengan jelas jauh lebih baik daripada diam-diam membaca semua tenant.
2. **`org_id` selalu dari konteks.** Saat membuat baris baru, repository mengisi `org_id` dari tenant aktif.
3. **`org_id` dari input dibuang.** Kalau klien mengirim body `{ "org_id": "<klinik lain>", ... }`, nilai itu tidak dipakai. Repository juga menambahkan `org_id` ke setiap filter.

```js
function buatRepo(tx) {
  const org = tx.currentSetting("app.org_id");
  if (!org) throw new Error("tenant_wajib");
  return {
    buat(tabel, { org_id, ...isi }) {
      return tx.insert(tabel, { ...isi, org_id: org });
    },
  };
}
```

Perhatikan destructuring `{ org_id, ...isi }`. Variabel `org_id` sengaja diambil lalu tidak dipakai, sehingga `isi` berisi semua field kecuali `org_id`. Dengan RLS saja, insert ber-`org_id` palsu akan gagal dengan error. Dengan repository, baris itu justru masuk ke tenant sendiri, yang memang maksud pengguna yang sah.

Semua akses tetap lewat satu pintu: `withTenant(userId, orgId, fn)` memasang konteks, dan di dalam `fn` kode memakai repository.

## Tes serangan lintas tenant

Isolasi tidak boleh hanya diyakini. Ia harus dibuktikan dengan tes yang berperan sebagai penyerang. Siapkan dua organisasi, A dan B, masing-masing dengan data. Lalu dari dalam tenant A, jalankan skenario berikut:

- **Baca dengan filter tenant lain**: `select * from bookings where org_id = <B>` harus menghasilkan nol baris. Ini menguji bahwa filter manual pun tidak bisa menembus policy.
- **Insert ke tenant lain**: insert baris dengan `org_id = B` harus ditolak oleh `WITH CHECK`.
- **Update dan delete lintas tenant**: perintah ke baris milik B harus mengenai nol baris.
- **Tanpa konteks**: transaksi `app_user` tanpa `set_config` tidak boleh melihat apa pun.
- **Audit tidak bisa dihapus**: `delete from audit_log` oleh `app_user` harus gagal, karena role itu hanya diberi hak `select, insert`.

![Tes serangan lintas tenant](slide:13)

Contoh satu tes dengan test runner bawaan Node, seperti di Studio:

```ts
test("filter org_id B dari dalam A tetap nol baris", async () => {
  const rows = await withTenant("alice", A, (tx) =>
    tx`select * from bookings where org_id = ${B}`);
  assert.equal(rows.length, 0);
});
```

Setiap tabel milik tenant yang kamu tambahkan nanti, misalnya `services` atau `staff_schedules`, wajib mendapat tes yang sama. Jadikan ini kebiasaan saat menulis migrasi: tabel baru, RLS, policy, tes.

## Menyiapkan data uji

Tes serangan butuh dua tenant yang benar-benar ada di database. Masalahnya, `app_user` tidak bisa membuat data untuk dua tenant sekaligus, karena memang itu yang dilarang RLS. Data uji disiapkan dengan koneksi `app_system`, lalu tesnya sendiri memakai `withTenant`, yang terhubung sebagai `app_user`.

```ts
const A = randomUUID();
const B = randomUUID();

before(async () => {
  await sqlSystem`insert into orgs (id, name)
    values (${A}, 'Klinik A'), (${B}, 'Salon B')`;
  await sqlSystem`insert into memberships (org_id, user_id, role)
    values (${A}, 'alice', 'owner'), (${B}, 'bob', 'owner')`;
});

after(async () => {
  await sqlSystem`delete from orgs where id in (${A}, ${B})`;
});
```

Dua kebiasaan kecil di sini membuat tes lebih andal. Pertama, id organisasi dibuat acak dengan `randomUUID()` setiap kali tes jalan, sehingga tes tidak bentrok dengan data sisa tes sebelumnya atau tes lain yang berjalan paralel. Kedua, pembersihan cukup menghapus baris `orgs`, karena semua tabel milik tenant memakai `on delete cascade`. Tes sekaligus membuktikan bahwa cascade itu bekerja.

Ini juga satu-satunya tempat kode tes boleh memakai `sqlSystem`. Assert-nya selalu dijalankan lewat jalur yang sama dengan request web.

## Postgres sungguhan, bukan mock

Tes isolasi harus berjalan terhadap Postgres sungguhan. Mock database hanya mengembalikan apa yang kamu suruh, jadi tidak pernah menguji policy, role, atau grant. Di CI, jalankan Postgres sebagai service container, jalankan migrasi dengan role pemilik, lalu jalankan tes dengan koneksi `app_user`, persis seperti aplikasi di produksi.

Ada satu detail penting: tes harus terhubung sebagai role yang sama dengan aplikasi. Kalau tes memakai koneksi pemilik tabel, semua tes akan "lulus" karena pemilik melewati RLS, padahal policy-nya tidak pernah diuji. Inilah salah satu alasan `FORCE ROW LEVEL SECURITY` kadang dipakai di lingkungan tes.

## Membuktikan tes bisa merah

Tes yang tidak pernah gagal belum tentu menguji apa pun. Mungkin ia memakai koneksi yang salah, mungkin assert-nya tidak pernah tercapai. Cara membuktikannya sederhana tapi jarang dilakukan:

1. Hapus sementara baris `enable row level security` untuk `bookings` di migrasi.
2. Migrasi ulang database tes, lalu jalankan tes isolasi.
3. Tes harus **merah**. Catat tes mana yang gagal.
4. Kembalikan migrasinya dan pastikan semua hijau lagi.

Kalau di langkah 3 semua tes tetap hijau, tesmu tidak menguji RLS sama sekali.

Tes yang merah pun perlu dibaca dengan teliti. Saat RLS dimatikan, kamu berharap tes baca lintas tenant, insert ke tenant lain, delete lintas tenant, dan tanpa konteks ikut gagal. Kalau hanya sebagian yang merah, cari tahu kenapa sisanya tetap hijau. Bisa jadi tes itu kebetulan lulus karena data ujinya kosong, misalnya tenant B belum punya booking sama sekali. Teknik sengaja merusak kode untuk menguji tes seperti ini mirip ide di balik mutation testing. Latihan kedua di bab ini meniru langkah tersebut: fungsi `ujiIsolasi` dijalankan pada database yang RLS-nya benar dan pada database yang sengaja dirusak.

## Menjaga pintu koneksi sistem

Koneksi `app_system` dipakai webhook dan worker, dan ia boleh lintas tenant. Bahayanya, seseorang di tim bisa mengimpornya ke route web karena "lebih gampang". Satu import itu meniadakan seluruh kerja RLS untuk route tersebut.

Studio menambahkan pemeriksaan sederhana di CI: cari kata `sqlSystem` di folder route web. Bila ditemukan, CI gagal.

```bash
if grep -rn "sqlSystem" app/; then
  echo "route web tidak boleh memakai koneksi sistem"; exit 1
fi
```

Pemeriksaan sesederhana ini sering lebih efektif daripada aturan tertulis di dokumen, karena ia dijalankan di setiap pull request tanpa perlu diingat.

## Rangkuman

- Pertahanan berlapis: repository dengan tenant wajib di atas RLS, sehingga satu kesalahan tidak langsung menjadi kebocoran.
- Repository melempar `tenant_wajib` tanpa konteks, mengisi `org_id` dari konteks, dan membuang `org_id` dari input.
- Tes serangan wajib: baca dengan filter tenant lain, insert ke tenant lain, update dan delete lintas tenant, tanpa konteks, dan hapus `audit_log`.
- Jalankan tes terhadap Postgres sungguhan dengan role aplikasi, buktikan tes bisa merah dengan mematikan RLS sementara, dan cegah route web mengimpor koneksi sistem.

