function buatRepo(tx) {
  const org = tx.currentSetting("app.org_id");
  if (!org) throw new Error("tenant_wajib");
  const milikku = (filter = {}) => ({ ...filter, org_id: org });
  const bersih = ({ org_id, ...isi }) => isi;
