solution.code:
async function ujiIsolasi(db) {
  const bocor = [];
  const dariA = (fn) => withTenant(db, "rani", "A", fn);

  const baca = await dariA((tx) => tx.select("bookings", { org_id: "B" }));
  if (baca.length > 0) bocor.push("baca-lintas");

  const masuk = await dariA((tx) => tx.insert("bookings", { org_id: "B", client_name: "Penyusup" })).then(() => true, () => false);
  if (masuk) bocor.push("insert-lintas");

  const hapus = await dariA((tx) => tx.delete("bookings", { org_id: "B" }));
  if (hapus > 0) bocor.push("hapus-lintas");

  const tanpa = await db.transaksi((tx) => tx.select("bookings"));
  if (tanpa.length > 0) bocor.push("tanpa-konteks");

  return bocor;
}

