// Sample data: clinic A (rani) and clinic B (budi). siapkan({ rls: false }) or
// siapkan({ cekTulis: false }) builds a deliberately broken database.
function siapkan({ rls = true, cekTulis = true } = {}) {
  const db = buatDb();
  db.tabel.memberships = [{ org_id: "A", user_id: "rani", role: "owner" }, { org_id: "B", user_id: "budi", role: "owner" }];
  db.tabel.bookings = [
    { id: "a1", org_id: "A", client_name: "Sari" },
    { id: "b1", org_id: "B", client_name: "Kucing Oyen" },
  ];
  if (rls) db.aktifkanRls("bookings");
  db.policy("bookings", {
    using: (b, tx) => b.org_id === tx.currentSetting("app.org_id"),
    withCheck: cekTulis ? undefined : () => true,
  });
  return db;
}
// withTenant from chapter 3 (memberships without RLS here, to keep it short).
function withTenant(db, userId, orgId, fn) {
  return db.transaksi(async (tx) => {
    tx.setConfig("app.user_id", userId);
    if (!tx.select("memberships", { org_id: orgId, user_id: userId }).length) throw new Forbidden("bukan anggota");
    tx.setConfig("app.org_id", orgId);
    return fn(tx);
  });
}
