function buatUndangan(store, actor, email, role, acak, jam) {
  if (!canManage(actor.role, role)) throw new Error("forbidden");
  const token = acak();
  store.invites.push({
    org_id: actor.org_id,
    email: email.trim().toLowerCase(),
    role,
    token_hash: sha256Hex(token),
    expires_at: jam.t + 7 * HARI,
    accepted_at: null,
  });
  return token;
}

function terimaUndangan(store, userId, emailSesi, token, jam) {
  const hash = sha256Hex(token);
  const email = emailSesi.trim().toLowerCase();
  const inv = store.invites.find((i) =>
    i.token_hash === hash && i.accepted_at === null && i.expires_at > jam.t && i.email === email);
  if (!inv) throw new Error("undangan_tidak_valid");
  inv.accepted_at = jam.t;
  store.memberships.push({ org_id: inv.org_id, user_id: userId, role: inv.role });
  return inv.org_id;
}

