function ubahRole(anggota, actorId, targetId, roleBaru) {
  const actor = anggota.find((a) => a.user_id === actorId);
  const target = anggota.find((a) => a.user_id === targetId);
  if (!actor || !target) throw new Error("tidak_ditemukan");
  const diriSendiri = actorId === targetId && actor.role === "owner";
  const bolehUbah = canManage(actor.role, target.role) &&
    (roleBaru === "owner" ? actor.role === "owner" : canManage(actor.role, roleBaru));
  if (!diriSendiri && !bolehUbah) throw new Error("forbidden");
  const jumlahOwner = anggota.filter((a) => a.role === "owner").length;
  if (target.role === "owner" && roleBaru !== "owner" && jumlahOwner === 1) throw new Error("owner_terakhir");
  target.role = roleBaru;
  return anggota;
}

