solution.code:
function tenantAction(handler) {
  return async (req) => {
    const session = await getSession(req);
    if (!session) return { status: 401, body: { error: "Belum masuk." } };
    try {
      const data = await withTenant(session.user.id, req.params.orgId, (tx, role) =>
        handler(tx, { id: session.user.id, role }));
      return { status: 200, body: data };
    } catch (err) {
      if (err && (err.status === 403 || err.status === 429)) {
        return { status: err.status, body: { error: err.message } };
      }
      if (err && String(err.message).startsWith("plan_limit:")) {
        return { status: 402, body: { error: "Batas paketmu tercapai. Naikkan paket untuk lanjut.", code: err.message } };
      }
      logServer.push(String(err && err.message));
      return { status: 500, body: { error: "Terjadi kesalahan. Coba lagi sebentar." } };
    }
  };
}

