class Forbidden extends Error { constructor(m = "Kamu bukan anggota organisasi ini.") { super(m); this.status = 403; } }
class TooManyRequests extends Error { constructor(m = "Terlalu banyak request, coba lagi sebentar.") { super(m); this.status = 429; } }
