solution.code:
const TRIAL_HARI = 14;
const TENGGANG_HARI = 7;

function statusLangganan(org, jam) {
  const akhir = org.paid_until ?? org.created_at + TRIAL_HARI * HARI;
  if (jam.t < akhir) return org.paid_until ? "aktif" : "trial";
  if (jam.t < akhir + TENGGANG_HARI * HARI) return "tenggang";
  return "terkunci";
}

function validSignature(notif, serverKey) {
  const { order_id, status_code, gross_amount, signature_key } = notif;
  if (!order_id || !status_code || !gross_amount || !signature_key) return false;
  const expected = sha512Hex(order_id + status_code + gross_amount + serverKey);
  return timingSafeEqualTeks(signature_key, expected);
}

