solution.code:
const GAGAL = ["deny", "cancel", "expire", "failure"];

function terapkanNotifikasi(store, n) {
  const key = n.order_id + ":" + n.transaction_status;
  if (store.events.has(key)) return "duplikat";
  store.events.add(key);

  const order = store.orders.find((o) => o.order_id === n.order_id);
  if (GAGAL.includes(n.transaction_status)) {
    if (order && order.status === "pending") order.status = "failed";
    return "gagal";
  }
  const sukses = n.transaction_status === "settlement" ||
    (n.transaction_status === "capture" && n.fraud_status === "accept");
  if (!sukses) return "diabaikan";
  if (!order || order.status === "paid" || order.gross_amount !== Number(n.gross_amount)) return "diabaikan";

  order.status = "paid";
  const org = store.orgs[order.org_id];
  org.plan_id = order.plan_id;
  org.paid_until = Math.max(org.paid_until ?? 0, store.jam.t) + BULAN;
  store.audit.push({ org_id: order.org_id, actor_id: "system:midtrans", action: "billing.paid", target: n.order_id });
  return "dibayar";
}

