// A small in-memory store standing in for billing_orders, orgs, webhook_events and audit_log.
const HARI = 24 * 60 * 60 * 1000, BULAN = 30 * HARI; // "1 month" simplified to 30 days
const jam = { t: 100 * HARI, maju(ms) { this.t += ms; } };
function buatStore() {
  return {
    jam,
