const KUNCI_MS = 5 * 60 * 1000;

function ambilJob(antrean, jam) {
  let pilih = null;
  for (const j of antrean) {
    const siap = j.done_at === null && j.run_at <= jam.t && j.attempts < j.max_attempts &&
      (j.locked_until === null || j.locked_until <= jam.t);
    if (siap && (!pilih || j.run_at < pilih.run_at)) pilih = j;
  }
  if (!pilih) return null;
  pilih.attempts += 1;
  pilih.locked_until = jam.t + KUNCI_MS;
  return pilih;
}

function selesaikan(job, jam) {
  job.done_at = jam.t;
  job.locked_until = null;
  job.last_error = null;
}

function gagalkan(job, err, jam) {
  job.last_error = err.message;
  job.locked_until = null;
  job.run_at = jam.t + Math.min(30 * 2 ** job.attempts, 3600) * 1000;
  return job.attempts >= job.max_attempts ? "menyerah" : "coba-lagi";
}

