function rateLimit(store, orgId, bucket, batas, jam, jendelaDetik = 60) {
  const detik = Math.floor(jam.t / 1000);
  const awal = Math.floor(detik / jendelaDetik) * jendelaDetik;
  const kunci = orgId + "|" + bucket + "|" + awal;
  store[kunci] = (store[kunci] || 0) + 1;
  if (store[kunci] > batas) {
    throw new TooManyRequests(Math.ceil(((awal + jendelaDetik) * 1000 - jam.t) / 1000));
  }
  return store[kunci];
}

function cekKuota(org, plans, pemakaian, aksi) {
  const plan = plans.find((p) => p.id === org.plan_id);
  if (!plan) throw new Error("paket tidak dikenal");
  const [batas, pakai, kode] = aksi === "staff"
    ? [plan.max_staff, pemakaian.staff, "plan_limit:staff"]
    : [plan.max_bookings_per_month, pemakaian.bookings, "plan_limit:bookings"];
  if (pakai >= batas) {
    const err = new Error(kode);
    err.status = 402;
    throw err;
  }
  return batas - pakai - 1;
}

