solution.code:
const KUNCI_RAHASIA = ["token", "token_hash", "password"];

function buatAuditLog(jam) {
  const baris = [];
  return {
    catat(entri) {
      if (!entri.org_id || !entri.actor_id || !entri.action) throw new Error("audit_tidak_lengkap");
      const meta = entri.meta || {};
      if (Object.keys(meta).some((k) => KUNCI_RAHASIA.includes(k))) throw new Error("meta_rahasia");
      const e = { id: baris.length + 1, target: null, ...entri, meta, created_at: jam.t };
      baris.push(salin(e));
      return salin(e);
    },
    riwayat(orgId, filter = {}) {
      return baris
        .filter((e) => e.org_id === orgId)
        .filter((e) => !filter.action || e.action === filter.action)
        .filter((e) => !filter.actor_id || e.actor_id === filter.actor_id)
        .reverse()
        .map(salin);
    },
    ubah() { throw new Error("audit_log append-only"); },
    hapus() { throw new Error("audit_log append-only"); },
  };
}

