function eksporTenant(db, orgId) {
  const hasil = {};
  for (const tabel of MILIK_TENANT) {
    hasil[tabel] = db[tabel]
      .filter((b) => b.org_id === orgId)
      .map((b) => {
        const salinan = { ...b };
        for (const k of KOLOM_RAHASIA) delete salinan[k];
        return salinan;
      });
  }
  return hasil;
}

function ringkasLog(baris) {
  const kelompok = {};
  for (const b of baris) {
    if (!b.org_id) continue;
    (kelompok[b.org_id] ??= []).push(b);
  }
  const hasil = {};
  for (const [org, daftar] of Object.entries(kelompok)) {
    const ms = daftar.map((b) => b.ms).sort((a, b) => a - b);
    hasil[org] = {
      request: daftar.length,
      error: daftar.filter((b) => b.level === "error").length,
      p95: ms[Math.ceil(0.95 * ms.length) - 1],
    };
  }
  return hasil;
}

